async function untilEndOpponentTurn(func , unit, type = 'units'){//dont ad to abilitieslist, do somekind of visual to show which one is resolving
  //amake changes to unit -> when end turn -> undo changes by running the needed function from endTurn object
  //run change function on unit, add reverse function to endTurn object


  let id = unit.id
  let existingFunctions = endOpponentTurnFunctions.current[type][id]

  if(existingFunctions ===  (null ||undefined)){
    
    endOpponentTurnFunctions.current[type] = {...endOpponentTurnFunctions.current[type] , [unit.id]:[func]}
  
  }
  else{
    endOpponentTurnFunctions.current[type] = {...endOpponentTurnFunctions.current[type] , [unit.id]: [...existingFunctions, func] }
  }
 
}


