async function searchZones(zone , propertyArray = basicPropertyArray){
  if(!zone){return []} 
  let newArr = []

  let check = searchUnit
  if(propertyArray[0].or){
    check = searchUnitOr
  }

  for(let j = 0; j<zone.length; j++){
    let card = zone[j]
    if(check(card , propertyArray)){
      newArr.push(card)
    }
    
  }
  return newArr

}

