function ifYourSoulHas4OrMoreDifferentGrades(){
  let foundGrades = {}
  let zone = userZones.soul
  for(let i =0;i<zone.length;i++){
    let grade = zone[i].tempGrade
    if(!foundGrades[grade]){
      foundGrades[grade] = true
    }
  }
let f = Object.keys(foundGrades)
if(f.length >=4){return true}
return false
}
