async function secondOrderCostCheck(firstCost, secondCost){ 
  let keys = Object.keys(secondCost)
  let tempSecond = {...secondCost}
  let canPay = true

  let playerAbilities =  playerFunctions.current['Alchemagic']
  if(playerAbilities){ 
    

  for(let i =0; i<playerAbilities.length ; i++){
 
   playerAbilities[i].effect( {cost:tempSecond})

 }
}
 for(let i =0;i<keys.length-1;i++){
  let key = keys[i]

    let findZone = await playerResources.current[key]({} , secondCost[key].zone) 
   
    let zoneL = await findHowManyCards(findZone, secondCost[key].filter )
    


  if(firstCost[key]){
    //check if more annd costchecker 

    let dif = zoneL - firstCost[key].amount
    if(tempSecond[key].amount > dif){
canPay = false
    }
  }
  else{
     //do normal cost check
     if(tempSecond[key].amount > zoneL){
      canPay = false
          }
  }
 
} 
  
  return canPay
}
async function checkAlchemagic(firstOrder){

  if (playerObjects.current.canAlchemagic === false ){
    return firstOrder
  }
   turnState.current.event = 'Alchemagic' 

 let secondOrder =  await getSecondOrder.current(firstOrder)
 
  if(secondOrder===null){
    return firstOrder
  }

 
  return await alchemagic(firstOrder , secondOrder)


}

