async function getCrest(crestName){
let newCrests = crests.filter((card)=>card.name === crestName)
if(newCrests.length === 0){
timedDisplay('Crest error')
  return
}
  let crest = newCrests[0]
  crest['id'] = playerObjects.current.lastestCardId
  crest['abilities'] = await abilityGiver(abilities[crest.name + ' (Crest)'], crest.id ) // make give id func
  playerObjects.current.lastestCardId ++;
  userZones.crest.push(crest)
  setUserZones({...userZones})
}

