async function lock(unit, omegaLock = false){
  //resetunit then lock
  console.log(playerObjects)
  playerObjects.current.lockedCards[unit.circle] = {...await resetUnit(unit)}
  stand(unit)
  unit.canIntercept = false;
  unit.hasIntercept = false;
  unit.canBoost = false
  unit.hasBoost = false
  unit.stand = false
  unit.abilities = {}
  unit.canAttack = false
  unit.canBeAttacked = false
  unit.standInStand = false
  unit.canBeChosen = false
  unit.place = 'locked'
  unit.cardtype = 'locked'
  unit.race = 'locked'
  unit.clan = 'locked'
  unit.nation = 'locked'
  unit.name = 'locked'
  unit.grade = 0
  unit.power = 0
  unit.tempPower = 0
  unit.powerIncrease = 0
  unit.shield = 0
  unit.critical = 0
  unit.cannotBeMovedTo = Object.keys(userCircles)
  turnFaceDown(unit)
  unit['unlockEndPhase'] = true
  if(omegaLock){
    unit['unlockEndPhase'] = false
    untilEndTurn(()=>{
      unit.unlockEndPhase = true;
    }, unit)
  }
  console.log(playerObjects.current.lockedCards[unit.circle] )
}

