// faceup/down functions

function turnFaceDown(card){
  if(!card.faceup){return}
  let temp = card.img
  card.img = card.back
  card.back = temp
  card.faceup = false
}

function turnFaceUp(card){
  if(card.faceup){return}
  let temp = card.img
  card.img = card.back
  card.back = temp
  card.faceup = true
}

