//-cont ability
async function contAbilityCheck(ability , card){

   let condition = await ability.condition(card) 

  if(condition && ability.isOn === false){
    //turnState.current.card = card
    ability.on(card )
    ability.isOn = true

  }
  else if(condition === false && ability.isOn === true){
   
    ability.off(card )
   ability.isOn = false
  }

  return ability
}


